pragma solidity 0.8.15;

import "../vendor/@chainlink/contracts/src/v0.8/interfaces/AggregatorV3Interface.sol";

/**
 * @title Mock oracle
 * @notice Mock oracle to test the scaling price feed with updated update time
 * @author Compound
 */
contract MockRenzoOracle {

    /// @notice Number of decimals for returned prices
    uint8 public immutable decimals;

    /// @notice Underlying Chainlink price feed where prices are fetched from
    address public immutable underlyingPriceFeed;

    /**
     * @notice Construct a new scaling price feed
     * @param underlyingPriceFeed_ The address of the underlying price feed to fetch prices from
     **/
    constructor(address underlyingPriceFeed_) {
        underlyingPriceFeed = underlyingPriceFeed_;
        decimals = AggregatorV3Interface(underlyingPriceFeed_).decimals();
    }

    /**
     * @notice Price for the latest round
     * @return roundId Round id from the underlying price feed
     * @return answer Latest price for the asset in terms of ETH
     * @return startedAt Timestamp when the round was started; passed on from underlying price feed
     * @return updatedAt Current timestamp
     * @return answeredInRound Round id in which the answer was computed; passed on from underlying price feed
     **/
    function latestRoundData() external view returns (
        uint80 roundId,
        int256 answer,
        uint256 startedAt,
        uint256 updatedAt,
        uint80 answeredInRound
    ) {
        (uint80 roundId_, int256 price, uint256 startedAt_, , uint80 answeredInRound_) = AggregatorV3Interface(underlyingPriceFeed).latestRoundData();
        return (roundId_, price, startedAt_, block.timestamp, answeredInRound_);
    }
}
"},"contracts/CometStorage.sol":{"content":"// SPDX-License-Identifier: BUSL-1.1
pragma solidity 0.8.15;

/**
 * @title Compound's Comet Storage Interface
 * @dev Versions can enforce append-only storage slots via inheritance.
 * @author Compound
 */
contract CometStorage {
    // 512 bits total = 2 slots
    struct TotalsBasic {
        // 1st slot
        uint64 baseSupplyIndex;
        uint64 baseBorrowIndex;
        uint64 trackingSupplyIndex;
        uint64 trackingBorrowIndex;
        // 2nd slot
        uint104 totalSupplyBase;
        uint104 totalBorrowBase;
        uint40 lastAccrualTime;
        uint8 pauseFlags;
    }

    struct TotalsCollateral {
        uint128 totalSupplyAsset;
        uint128 _reserved;
    }

    struct UserBasic {
        int104 principal;
        uint64 baseTrackingIndex;
        uint64 baseTrackingAccrued;
        uint16 assetsIn;
        uint8 _reserved;
    }

    struct UserCollateral {
        uint128 balance;
        uint128 _reserved;
    }

    struct LiquidatorPoints {
        uint32 numAbsorbs;
        uint64 numAbsorbed;
        uint128 approxSpend;
        uint32 _reserved;
    }

    /// @dev Aggregate variables tracked for the entire market
    uint64 internal baseSupplyIndex;
    uint64 internal baseBorrowIndex;
    uint64 internal trackingSupplyIndex;
    uint64 internal trackingBorrowIndex;
    uint104 internal totalSupplyBase;
    uint104 internal totalBorrowBase;
    uint40 internal lastAccrualTime;
    uint8 internal pauseFlags;

    /// @notice Aggregate variables tracked for each collateral asset
    mapping(address => TotalsCollateral) public totalsCollateral;

    /// @notice Mapping of users to accounts which may be permitted to manage the user account
    mapping(address => mapping(address => bool)) public isAllowed;

    /// @notice The next expected nonce for an address, for validating authorizations via signature
    mapping(address => uint) public userNonce;

    /// @notice Mapping of users to base principal and other basic data
    mapping(address => UserBasic) public userBasic;

    /// @notice Mapping of users to collateral data per collateral asset
    mapping(address => mapping(address => UserCollateral)) public userCollateral;

    /// @notice Mapping of magic liquidator points
    mapping(address => LiquidatorPoints) public liquidatorPoints;

    /**
     * @notice The extended pause flags represented as a bitmap
     * @dev Each bit represents a pause flag for a different action
     */
    uint24 public extendedPauseFlags;

    /**
     * @notice The collaterals withdraw pause flags represented as a bitmap
     * @dev Each bit represents a pause flag for an asset index
     */
    uint24 public collateralsWithdrawPauseFlags;

    /**
     * @notice The collaterals supply pause flags represented as a bitmap
     * @dev Each bit represents a pause flag for an asset index
     */
    uint24 public collateralsSupplyPauseFlags;

    /**
     * @notice The collaterals transfer pause flags represented as a bitmap
     * @dev Each bit represents a pause flag for an asset index
     */
    uint24 public collateralsTransferPauseFlags;

    /**
     * @notice The deactivated collaterals flags represented as a bitmap
     * @dev Each bit represents whether a collateral asset is deactivated
     */
    uint24 public deactivatedCollaterals;
}
"},"contracts/test/PriceFeedWithRevert.sol":{"content":"// SPDX-License-Identifier: BUSL-1.1
pragma solidity 0.8.15;

import "../vendor/@chainlink/contracts/src/v0.8/interfaces/AggregatorV3Interface.sol";

contract PriceFeedWithRevert is AggregatorV3Interface {
    string public constant override description = "Mock Chainlink price aggregator";

    uint public constant override version = 1;

    uint8 public immutable override decimals;

    uint80 internal roundId;
    int256 internal answer;
    uint256 internal startedAt;
    uint256 internal updatedAt;
    uint80 internal answeredInRound;

    error Reverted();

    constructor(int answer_, uint8 decimals_) {
        answer = answer_;
        decimals = decimals_;
    }

    function setRoundData(
        uint80 roundId_,
        int256 answer_,
        uint256 startedAt_,
        uint256 updatedAt_,
        uint80 answeredInRound_
    ) public {
        roundId = roundId_;
        answer = answer_;
        startedAt = startedAt_;
        updatedAt = updatedAt_;
        answeredInRound = answeredInRound_;
    }

    function getRoundData(uint80 roundId_) override external view returns (uint80, int256, uint256, uint256, uint80) {
        return (roundId_, answer, startedAt, updatedAt, answeredInRound);
    }

    function latestRoundData() override external pure returns (uint80, int256, uint256, uint256, uint80) {
        revert Reverted();
    }
}
"},"contracts/CometExtInterface.sol":{"content":"// SPDX-License-Identifier: BUSL-1.1
pragma solidity 0.8.15;

import "./CometCore.sol";

/**
 * @title Compound's Comet Ext Interface
 * @notice An efficient monolithic money market protocol
 * @author Compound
 */
abstract contract CometExtInterface is CometCore {
    error BadAmount();
    error BadNonce();
    error BadSignatory();
    error InvalidValueS();
    error InvalidValueV();
    error SignatureExpired();

    /**
     * @dev Error thrown when the caller is not the pause guardian or governor
     */
    error OnlyPauseGuardianOrGovernor();
    /**
     * @dev Error thrown when the offset status is already set
     * @param offset The offset that is already set
     * @param status The status of the offset
     */
    error OffsetStatusAlreadySet(uint24 offset, bool status);
    /**
     * @dev Error thrown when the collateral asset offset status is already set
     * @param offset The offset that is already set
     * @param assetIndex The index of the collateral asset
     * @param status The status of the offset
     */
    error CollateralAssetOffsetStatusAlreadySet(uint24 offset, uint24 assetIndex, bool status);
    /**
     * @dev Error thrown when the asset index is invalid
     */
    error InvalidAssetIndex();
    /**
     * @dev Error thrown when the caller is not the pause guardian
     */
    error OnlyPauseGuardian();
    /**
     * @dev Error thrown when the caller is not the governor
     */
    error OnlyGovernor();
    /**
     * @dev Error thrown when the collateral asset is already deactivated
     * @param assetIndex The index of the collateral asset
     */
    error CollateralIsDeactivated(uint24 assetIndex);
    /**
     * @dev Error thrown when the collateral asset is already activated
     * @param assetIndex The index of the collateral asset
     */
    error CollateralIsActivated(uint24 assetIndex);

    function allow(address manager, bool isAllowed) virtual external;
    function allowBySig(address owner, address manager, bool isAllowed, uint256 nonce, uint256 expiry, uint8 v, bytes32 r, bytes32 s) virtual external;

    /*//////////////////////////////////////////////////////////////
                             PAUSE CONTROL
    //////////////////////////////////////////////////////////////*/
    /**
     * @notice Pauses or unpauses the ability for lenders to withdraw their assets.
     * @param paused Whether to pause (`true`) or unpause (`false`) lenders' withdrawals.
     */
    function pauseLendersWithdraw(bool paused) virtual external;
    /**
     * @notice Pauses or unpauses the ability for borrowers to withdraw their assets.
     * @param paused Whether to pause (`true`) or unpause (`false`) borrowers' withdrawals.
     */
    function pauseBorrowersWithdraw(bool paused) virtual external;
    /**
     * @notice Pauses or unpauses the ability to withdraw collateral.
     * @param paused Whether to pause (`true`) or unpause (`false`) collateral withdrawals.
     */
    function pauseCollateralWithdraw(bool paused) virtual external;
    /**
     * @notice Pauses or unpauses the ability to withdraw a specific collateral asset.
     * @param assetIndex The index of the collateral asset to pause/unpause.
     * @param paused Whether to pause (`true`) or unpause (`false`) withdrawals for the specified collateral asset.
     */
    function pauseCollateralAssetWithdraw(uint24 assetIndex, bool paused) virtual external;
    /**
     * @notice Pauses or unpauses the supply of collateral.
     * @param paused Whether to pause (`true`) or unpause (`false`) collateral supply actions.
     */
    function pauseCollateralSupply(bool paused) virtual external;
    /**
     * @notice Pauses or unpauses the supply of base assets.
     * @param paused Whether to pause (`true`) or unpause (`false`) base asset supply actions.
     */
    function pauseBaseSupply(bool paused) virtual external;
    /**
     * @notice Pauses or unpauses the supply of a specific collateral asset.
     * @param assetIndex The index of the collateral asset to pause/unpause.
     * @param paused Whether to pause (`true`) or unpause (`false`) supply actions for the specified collateral asset.
     */
    function pauseCollateralAssetSupply(uint24 assetIndex, bool paused) virtual external;
    /**
     * @notice Pauses or unpauses the ability for lenders to transfer their assets.
     * @param paused Whether to pause (`true`) or unpause (`false`) lenders' transfer actions.
     */
    function pauseLendersTransfer(bool paused) virtual external;
    /**
     * @notice Pauses or unpauses the ability for borrowers to transfer their assets.
     * @param paused Whether to pause (`true`) or unpause (`false`) borrowers' transfer actions.
     */
    function pauseBorrowersTransfer(bool paused) virtual external;
    /**
     * @notice Pauses or unpauses the ability to transfer collateral.
     * @param paused Whether to pause (`true`) or unpause (`false`) collateral transfer actions.
     */
    function pauseCollateralTransfer(bool paused) virtual external;
    /**
     * @notice Pauses or unpauses the ability to transfer a specific collateral asset.
     * @param assetIndex The index of the collateral asset to pause/unpause.
     * @param paused Whether to pause (`true`) or unpause (`false`) transfer actions for the specified collateral asset.
     */
    function pauseCollateralAssetTransfer(uint24 assetIndex, bool paused) virtual external;
    /**
     * @notice Deactivates a collateral asset.
     * @param assetIndex The index of the collateral asset to deactivate.
     */
    function deactivateCollateral(uint24 assetIndex) virtual external;
    /**
     * @notice Activates a collateral asset.
     * @param assetIndex The index of the collateral asset to activate.
     */
    function activateCollateral(uint24 assetIndex) virtual external;

    function collateralBalanceOf(address account, address asset) virtual external view returns (uint128);
    function baseTrackingAccrued(address account) virtual external view returns (uint64);

    function baseAccrualScale() virtual external view returns (uint64);
    function baseIndexScale() virtual external view returns (uint64);
    function factorScale() virtual external view returns (uint64);
    function priceScale() virtual external view returns (uint64);

    function maxAssets() virtual external view returns (uint8);

    function totalsBasic() virtual external view returns (TotalsBasic memory);

    function version() virtual external view returns (string memory);

    /**
      * ===== ERC20 interfaces =====
      * Does not include the following functions/events, which are defined in `CometMainInterface` instead:
      * - function decimals() virtual external view returns (uint8)
      * - function totalSupply() virtual external view returns (uint256)
      * - function transfer(address dst, uint amount) virtual external returns (bool)
      * - function transferFrom(address src, address dst, uint amount) virtual external returns (bool)
      * - function balanceOf(address owner) virtual external view returns (uint256)
      * - event Transfer(address indexed from, address indexed to, uint256 amount)
      */
    function name() virtual external view returns (string memory);
    function symbol() virtual external view returns (string memory);

    /**
      * @notice Approve `spender` to transfer up to `amount` from `src`
      * @dev This will overwrite the approval amount for `spender`
      *  and is subject to issues noted [here](https://eips.ethereum.org/EIPS/eip-20#approve)
      * @param spender The address of the account which may transfer tokens
      * @param amount The number of tokens that are approved (-1 means infinite)
      * @return Whether or not the approval succeeded
      */
    function approve(address spender, uint256 amount) virtual external returns (bool);

    /**
      * @notice Get the current allowance from `owner` for `spender`
      * @param owner The address of the account which owns the tokens to be spent
      * @param spender The address of the account which may transfer tokens
      * @return The number of tokens allowed to be spent (-1 means infinite)
      */
    function allowance(address owner, address spender) virtual external view returns (uint256);

    event Approval(address indexed owner, address indexed spender, uint256 amount);
    /**
     * @notice Emitted when the pause status for lenders' withdrawals is changed
     * @param lendersWithdrawPaused Whether lenders' withdrawals are now paused
     */
    event LendersWithdrawPauseAction(bool lendersWithdrawPaused);
    /**
     * @notice Emitted when the pause status for borrowers' withdrawals is changed
     * @param borrowersWithdrawPaused Whether borrowers' withdrawals are now paused
     */
    event BorrowersWithdrawPauseAction(bool borrowersWithdrawPaused);
    /**
     * @notice Emitted when the pause status for collateral withdrawals is changed
     * @param collateralWithdrawPaused Whether collateral withdrawals are now paused
     */
    event CollateralWithdrawPauseAction(bool collateralWithdrawPaused);
    /**
     * @notice Emitted when the pause status for a specific collateral asset's withdrawals is changed
     * @param assetIndex The index of the collateral asset
     * @param collateralAssetWithdrawPaused Whether withdrawals for this collateral asset are now paused
     */
    event CollateralAssetWithdrawPauseAction(uint24 assetIndex, bool collateralAssetWithdrawPaused);
    /**
     * @notice Emitted when the pause status for collateral supply is changed
     * @param collateralSupplyPaused Whether collateral supply is now paused
     */
    event CollateralSupplyPauseAction(bool collateralSupplyPaused);
    /**
     * @notice Emitted when the pause status for a specific collateral asset's supply is changed
     * @param assetIndex The index of the collateral asset
     * @param collateralAssetSupplyPaused Whether supply for this collateral asset is now paused
     */
    event CollateralAssetSupplyPauseAction(uint24 assetIndex, bool collateralAssetSupplyPaused);
    /**
     * @notice Emitted when the pause status for base supply is changed
     * @param baseSupplyPaused Whether base supply is now paused
     */
    event BaseSupplyPauseAction(bool baseSupplyPaused);
    /**
     * @notice Emitted when the pause status for lenders' transfers is changed
     * @param lendersTransferPaused Whether lenders' transfers are now paused
     */
    event LendersTransferPauseAction(bool lendersTransferPaused);
    /**
     * @notice Emitted when the pause status for borrowers' transfers is changed
     * @param borrowersTransferPaused Whether borrowers' transfers are now paused
     */
    event BorrowersTransferPauseAction(bool borrowersTransferPaused);
    /**
     * @notice Emitted when the pause status for collateral transfers is changed
     * @param collateralTransferPaused Whether collateral transfers are now paused
     */
    event CollateralTransferPauseAction(bool collateralTransferPaused);
    /**
     * @notice Emitted when the pause status for a specific collateral asset's transfers is changed
     * @param assetIndex The index of the collateral asset
     * @param collateralAssetTransferPaused Whether transfers for this collateral asset are now paused
     */
    event CollateralAssetTransferPauseAction(uint24 assetIndex, bool collateralAssetTransferPaused);
    /**
     * @notice Emitted when a collateral asset is deactivated
     * @param assetIndex The index of the collateral asset that was deactivated
     */
    event CollateralDeactivated(uint24 assetIndex);
    /**
     * @notice Emitted when a collateral asset is activated
     * @param assetIndex The index of the collateral asset that was activated
     */
    event CollateralActivated(uint24 assetIndex);
}"},"contracts/CometExt.sol":{"content":"// SPDX-License-Identifier: BUSL-1.1
pragma solidity 0.8.15;

import "./CometExtInterface.sol";
import "./CometMainInterface.sol";

contract CometExt is CometExtInterface {
    /** Public constants **/

    /// @notice The major version of this contract
    string public override constant version = "0";

    /** Internal constants **/

    /// @dev The EIP-712 typehash for the contract's domain
    bytes32 internal constant DOMAIN_TYPEHASH = keccak256("EIP712Domain(string name,string version,uint256 chainId,address verifyingContract)");

    /// @dev The EIP-712 typehash for allowBySig Authorization
    bytes32 internal constant AUTHORIZATION_TYPEHASH = keccak256("Authorization(address owner,address manager,bool isAllowed,uint256 nonce,uint256 expiry)");

    /// @dev The highest valid value for s in an ECDSA signature pair (0 < s < secp256k1n ÷ 2 + 1)
    ///  See https://ethereum.github.io/yellowpaper/paper.pdf #307)
    uint internal constant MAX_VALID_ECDSA_S = 0x7FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF5D576E7357A4501DDFE92F46681B20A0;

    /** Immutable symbol **/

    /// @dev The ERC20 name for wrapped base token
    bytes32 internal immutable name32;

    /// @dev The ERC20 symbol for wrapped base token
    bytes32 internal immutable symbol32;

    /** Modifiers **/

    /**
     * @dev Modifier to check if the sender is the governor or pause guardian
     */
    modifier onlyGovernorOrPauseGuardian() {
        if (msg.sender != CometMainInterface(address(this)).governor() && 
        msg.sender != CometMainInterface(address(this)).pauseGuardian()) 
            revert OnlyPauseGuardianOrGovernor();
        _;
    }

    /**
     * @dev Modifier to check if the asset index is valid
     * @param assetIndex The index of the asset
     */
    modifier isValidAssetIndex(uint24 assetIndex) {
        if (assetIndex >= CometMainInterface(address(this)).numAssets()) revert InvalidAssetIndex();
        _;
    }

    /**
     * @notice Construct a new protocol instance
     * @param config The mapping of initial/constant parameters
     **/
    constructor(ExtConfiguration memory config) {
        name32 = config.name32;
        symbol32 = config.symbol32;
    }

    /** External getters for internal constants **/

    function baseAccrualScale() override external pure returns (uint64) { return BASE_ACCRUAL_SCALE; }
    function baseIndexScale() override external pure returns (uint64) { return BASE_INDEX_SCALE; }
    function factorScale() override external pure returns (uint64) { return FACTOR_SCALE; }
    function priceScale() override external pure returns (uint64) { return PRICE_SCALE; }
    function maxAssets() override virtual external pure returns (uint8) { return MAX_ASSETS; }

    /**
     * @notice Aggregate variables tracked for the entire market
     **/
    function totalsBasic() public override view returns (TotalsBasic memory) {
        return TotalsBasic({
            baseSupplyIndex: baseSupplyIndex,
            baseBorrowIndex: baseBorrowIndex,
            trackingSupplyIndex: trackingSupplyIndex,
            trackingBorrowIndex: trackingBorrowIndex,
            totalSupplyBase: totalSupplyBase,
            totalBorrowBase: totalBorrowBase,
            lastAccrualTime: lastAccrualTime,
            pauseFlags: pauseFlags
        });
    }

    /** Additional ERC20 functionality and approval interface **/

    /**
     * @notice Get the ERC20 name for wrapped base token
     * @return The name as a string
     */
    function name() override public view returns (string memory) {
        uint8 i;
        for (i = 0; i < 32; ) {
            if (name32[i] == 0) {
                break;
            }
            unchecked { i++; }
        }
        bytes memory name_ = new bytes(i);
        for (uint8 j = 0; j < i; ) {
            name_[j] = name32[j];
            unchecked { j++; }
        }
        return string(name_);
    }

    /**
     * @notice Get the ERC20 symbol for wrapped base token
     * @return The symbol as a string
     */
    function symbol() override external view returns (string memory) {
        uint8 i;
        for (i = 0; i < 32; ) {
            if (symbol32[i] == 0) {
                break;
            }
            unchecked { i++; }
        }
        bytes memory symbol_ = new bytes(i);
        for (uint8 j = 0; j < i; ) {
            symbol_[j] = symbol32[j];
            unchecked { j++; }
        }
        return string(symbol_);
    }

    /**
     * @notice Query the current collateral balance of an account
     * @param account The account whose balance to query
     * @param asset The collateral asset to check the balance for
     * @return The collateral balance of the account
     */
    function collateralBalanceOf(address account, address asset) override external view returns (uint128) {
        return userCollateral[account][asset].balance;
    }

    /**
     * @notice Query the total accrued base rewards for an account
     * @param account The account to query
     * @return The accrued rewards, scaled by `BASE_ACCRUAL_SCALE`
     */
    function baseTrackingAccrued(address account) override external view returns (uint64) {
        return userBasic[account].baseTrackingAccrued;
    }

    /**
      * @notice Approve or disallow `spender` to transfer on sender's behalf
      * @dev Note: this binary approval is unlike most other ERC20 tokens
      * @dev Note: this grants full approval for spender to manage *all* the owner's assets
      * @param spender The address of the account which may transfer tokens
      * @param amount Either uint.max (to allow) or zero (to disallow)
      * @return Whether or not the approval change succeeded
      */
    function approve(address spender, uint256 amount) override external returns (bool) {
        if (amount == type(uint256).max) {
            allowInternal(msg.sender, spender, true);
        } else if (amount == 0) {
            allowInternal(msg.sender, spender, false);
        } else {
            revert BadAmount();
        }
        return true;
    }

    /**
      * @notice Get the current allowance from `owner` for `spender`
      * @dev Note: this binary allowance is unlike most other ERC20 tokens
      * @dev Note: this allowance allows spender to manage *all* the owner's assets
      * @param owner The address of the account which owns the tokens to be spent
      * @param spender The address of the account which may transfer tokens
      * @return Either uint.max (spender is allowed) or zero (spender is disallowed)
      */
    function allowance(address owner, address spender) override external view returns (uint256) {
        return hasPermission(owner, spender) ? type(uint256).max : 0;
    }

    /**
     * @notice Allow or disallow another address to withdraw, or transfer from the sender
     * @param manager The account which will be allowed or disallowed
     * @param isAllowed_ Whether to allow or disallow
     */
    function allow(address manager, bool isAllowed_) override external {
        allowInternal(msg.sender, manager, isAllowed_);
    }

    /**
     * @dev Stores the flag marking whether the manager is allowed to act on behalf of owner
     */
    function allowInternal(address owner, address manager, bool isAllowed_) internal {
        isAllowed[owner][manager] = isAllowed_;
        emit Approval(owner, manager, isAllowed_ ? type(uint256).max : 0);
    }

    /**
     * @notice Sets authorization status for a manager via signature from signatory
     * @param owner The address that signed the signature
     * @param manager The address to authorize (or rescind authorization from)
     * @param isAllowed_ Whether to authorize or rescind authorization from manager
     * @param nonce The next expected nonce value for the signatory
     * @param expiry Expiration time for the signature
     * @param v The recovery byte of the signature
     * @param r Half of the ECDSA signature pair
     * @param s Half of the ECDSA signature pair
     */
    function allowBySig(
        address owner,
        address manager,
        bool isAllowed_,
        uint256 nonce,
        uint256 expiry,
        uint8 v,
        bytes32 r,
        bytes32 s
    ) override external {
        if (uint256(s) > MAX_VALID_ECDSA_S) revert InvalidValueS();
        // v ∈ {27, 28} (source: https://ethereum.github.io/yellowpaper/paper.pdf #308)
        if (v != 27 && v != 28) revert InvalidValueV();
        bytes32 domainSeparator = keccak256(abi.encode(DOMAIN_TYPEHASH, keccak256(bytes(name())), keccak256(bytes(version)), block.chainid, address(this)));
        bytes32 structHash = keccak256(abi.encode(AUTHORIZATION_TYPEHASH, owner, manager, isAllowed_, nonce, expiry));
        bytes32 digest = keccak256(abi.encodePacked("\x19\x01", domainSeparator, structHash));
        address signatory = ecrecover(digest, v, r, s);
        if (signatory == address(0)) revert BadSignatory();
        if (owner != signatory) revert BadSignatory();
        if (nonce != userNonce[signatory]++) revert BadNonce();
        if (block.timestamp >= expiry) revert SignatureExpired();
        allowInternal(signatory, manager, isAllowed_);
    }

    /*//////////////////////////////////////////////////////////////
                        EXTENDED PAUSE CONTROL
    //////////////////////////////////////////////////////////////*/

    /**
     * @notice Set the status of a pause offset
     * @param offset The offset to set
     * @param paused The new status of the pause offset
     */
    function setPauseFlag(uint24 offset, bool paused) internal {
        paused ? extendedPauseFlags |= (uint24(1) << offset) : extendedPauseFlags &= ~(uint24(1) << offset);
    }

    /**
     * @notice Get the current status of a pause offset
     * @param offset The offset to check
     * @return The current status of the pause offset
     */
    function currentPauseOffsetStatus(uint24 offset) internal view returns (bool) {
        return (extendedPauseFlags & (uint24(1) << offset)) != 0;
    }

    /**
     * @notice Check if the collateral asset is deactivated
     * @param assetIndex The index of the collateral asset
     * @return Whether the collateral asset is deactivated
     */
    function isCollateralDeactivated(uint24 assetIndex) public view returns (bool) {
        return (deactivatedCollaterals & (uint24(1) << assetIndex) != 0) == true;
    }

    /**
     * @inheritdoc CometExtInterface
     */
    function pauseLendersWithdraw(bool paused) override external onlyGovernorOrPauseGuardian {
        if (currentPauseOffsetStatus(PAUSE_LENDERS_WITHDRAW_OFFSET) == paused) revert OffsetStatusAlreadySet(PAUSE_LENDERS_WITHDRAW_OFFSET, paused);

        setPauseFlag(PAUSE_LENDERS_WITHDRAW_OFFSET, paused);

        emit LendersWithdrawPauseAction(paused);
    }

    /**
     * @inheritdoc CometExtInterface
     */
    function pauseBorrowersWithdraw(bool paused) override external onlyGovernorOrPauseGuardian {
        if (currentPauseOffsetStatus(PAUSE_BORROWERS_WITHDRAW_OFFSET) == paused) revert OffsetStatusAlreadySet(PAUSE_BORROWERS_WITHDRAW_OFFSET, paused);

        setPauseFlag(PAUSE_BORROWERS_WITHDRAW_OFFSET, paused);

        emit BorrowersWithdrawPauseAction(paused);
    }

    /**
     * @inheritdoc CometExtInterface
     */
    function pauseCollateralWithdraw(bool paused) override external onlyGovernorOrPauseGuardian {
        if (currentPauseOffsetStatus(PAUSE_COLLATERALS_WITHDRAW_OFFSET) == paused) revert OffsetStatusAlreadySet(PAUSE_COLLATERALS_WITHDRAW_OFFSET, paused);

        setPauseFlag(PAUSE_COLLATERALS_WITHDRAW_OFFSET, paused);

        emit CollateralWithdrawPauseAction(paused);
    }

    /**
     * @inheritdoc CometExtInterface
     */
    function pauseCollateralAssetWithdraw(uint24 assetIndex, bool paused) override external onlyGovernorOrPauseGuardian isValidAssetIndex(assetIndex) {
        if ((collateralsWithdrawPauseFlags & (uint24(1) << assetIndex) != 0) == paused) revert CollateralAssetOffsetStatusAlreadySet(collateralsWithdrawPauseFlags, assetIndex, paused);

        paused ? collateralsWithdrawPauseFlags |= (uint24(1) << assetIndex) : collateralsWithdrawPauseFlags &= ~(uint24(1) << assetIndex);

        emit CollateralAssetWithdrawPauseAction(assetIndex, paused);
    }

    /**
     * @inheritdoc CometExtInterface
     */
    function pauseCollateralSupply(bool paused) override external onlyGovernorOrPauseGuardian {
        if (currentPauseOffsetStatus(PAUSE_COLLATERAL_SUPPLY_OFFSET) == paused) revert OffsetStatusAlreadySet(PAUSE_COLLATERAL_SUPPLY_OFFSET, paused);

        setPauseFlag(PAUSE_COLLATERAL_SUPPLY_OFFSET, paused);

        emit CollateralSupplyPauseAction(paused);
    }

    /**
     * @inheritdoc CometExtInterface
     */
    function pauseBaseSupply(bool paused) override external onlyGovernorOrPauseGuardian {
        if (currentPauseOffsetStatus(PAUSE_BASE_SUPPLY_OFFSET) == paused) revert OffsetStatusAlreadySet(PAUSE_BASE_SUPPLY_OFFSET, paused);

        setPauseFlag(PAUSE_BASE_SUPPLY_OFFSET, paused);

        emit BaseSupplyPauseAction(paused);
    }

    /**
     * @inheritdoc CometExtInterface
     */
    function pauseCollateralAssetSupply(uint24 assetIndex, bool paused) override external onlyGovernorOrPauseGuardian isValidAssetIndex(assetIndex) {
        if ((collateralsSupplyPauseFlags & (uint24(1) << assetIndex) != 0) == paused) revert CollateralAssetOffsetStatusAlreadySet(collateralsSupplyPauseFlags, assetIndex, paused);
        if (!paused && isCollateralDeactivated(assetIndex)) revert CollateralIsDeactivated(assetIndex);

        paused ? collateralsSupplyPauseFlags |= (uint24(1) << assetIndex) : collateralsSupplyPauseFlags &= ~(uint24(1) << assetIndex);

        emit CollateralAssetSupplyPauseAction(assetIndex, paused);
    }

    /**
     * @inheritdoc CometExtInterface
     */
    function pauseLendersTransfer(bool paused) override external onlyGovernorOrPauseGuardian {
        if (currentPauseOffsetStatus(PAUSE_LENDERS_TRANSFER_OFFSET) == paused) revert OffsetStatusAlreadySet(PAUSE_LENDERS_TRANSFER_OFFSET, paused);

        setPauseFlag(PAUSE_LENDERS_TRANSFER_OFFSET, paused);

        emit LendersTransferPauseAction(paused);
    }

    /**
     * @inheritdoc CometExtInterface
     */
    function pauseBorrowersTransfer(bool paused) override external onlyGovernorOrPauseGuardian {
        if (currentPauseOffsetStatus(PAUSE_BORROWERS_TRANSFER_OFFSET) == paused) revert OffsetStatusAlreadySet(PAUSE_BORROWERS_TRANSFER_OFFSET, paused);

        setPauseFlag(PAUSE_BORROWERS_TRANSFER_OFFSET, paused);

        emit BorrowersTransferPauseAction(paused);
    }

    /**
     * @inheritdoc CometExtInterface
     */
    function pauseCollateralTransfer(bool paused) override external onlyGovernorOrPauseGuardian {
        if (currentPauseOffsetStatus(PAUSE_COLLATERALS_TRANSFER_OFFSET) == paused) revert OffsetStatusAlreadySet(PAUSE_COLLATERALS_TRANSFER_OFFSET, paused);

        setPauseFlag(PAUSE_COLLATERALS_TRANSFER_OFFSET, paused);

        emit CollateralTransferPauseAction(paused);
    }

    /**
     * @inheritdoc CometExtInterface
     */
    function pauseCollateralAssetTransfer(uint24 assetIndex, bool paused) override external onlyGovernorOrPauseGuardian isValidAssetIndex(assetIndex) {
        if ((collateralsTransferPauseFlags & (uint24(1) << assetIndex) != 0) == paused) revert CollateralAssetOffsetStatusAlreadySet(collateralsTransferPauseFlags, assetIndex, paused);
        if (!paused && isCollateralDeactivated(assetIndex)) revert CollateralIsDeactivated(assetIndex);

        paused ? collateralsTransferPauseFlags |= (uint24(1) << assetIndex) : collateralsTransferPauseFlags &= ~(uint24(1) << assetIndex);

        emit CollateralAssetTransferPauseAction(assetIndex, paused);
    }

    /**
     * @inheritdoc CometExtInterface
     */
    function deactivateCollateral(uint24 assetIndex) override external isValidAssetIndex(assetIndex) {
        if (msg.sender != CometMainInterface(address(this)).pauseGuardian()) revert OnlyPauseGuardian();
        if (isCollateralDeactivated(assetIndex)) revert CollateralIsDeactivated(assetIndex);

        // Mark collateral as deactivated
        deactivatedCollaterals |= (uint24(1) << assetIndex);
        emit CollateralDeactivated(assetIndex);

        // Pause supply of this collateral
        collateralsSupplyPauseFlags |= (uint24(1) << assetIndex);
        emit CollateralAssetSupplyPauseAction(assetIndex, true);

        // Pause transfer of this collateral
        collateralsTransferPauseFlags |= (uint24(1) << assetIndex);
        emit CollateralAssetTransferPauseAction(assetIndex, true);
    }

    /**
     * @inheritdoc CometExtInterface
     */
    function activateCollateral(uint24 assetIndex) override external isValidAssetIndex(assetIndex) {
        if (msg.sender != CometMainInterface(address(this)).governor()) revert OnlyGovernor();
        if ((deactivatedCollaterals & (uint24(1) << assetIndex) != 0) == false) revert CollateralIsActivated(assetIndex);

        // Mark collateral as activated
        deactivatedCollaterals &= ~(uint24(1) << assetIndex);
        emit CollateralActivated(assetIndex);

        // Unpause supply of this collateral
        collateralsSupplyPauseFlags &= ~(uint24(1) << assetIndex);
        emit CollateralAssetSupplyPauseAction(assetIndex, false);

        // Unpause transfer of this collateral
        collateralsTransferPauseFlags &= ~(uint24(1) << assetIndex);
        emit CollateralAssetTransferPauseAction(assetIndex, false);
    }
}"},"contracts/liquidator/vendor/@uniswap/v3-periphery/contracts/interfaces/external/IWETH9.sol":{"content":"// SPDX-License-Identifier: GPL-2.0-or-later
