/**
 * @dev Interface for interacting with Governor bravo.
 * Note Not a comprehensive interface
 */
interface IGovernorBravo {
    enum ProposalState {
        Pending,
        Active,
        Canceled,
        Defeated,
        Succeeded,
        Queued,
        Expired,
        Executed
    }

    struct Proposal {
        uint id;
        address proposer;
        uint eta;
        uint startBlock;
        uint endBlock;
        uint forVotes;
        uint againstVotes;
        uint abstainVotes;
        bool canceled;
        bool executed;
    }

    event ProposalCreated(
        uint256 proposalId,
        address proposer,
        address[] targets,
        uint256[] values,
        string[] signatures,
        bytes[] calldatas,
        uint256 startBlock,
        uint256 endBlock,
        string description
    );
    event ProposalCanceled(uint256 proposalId);
    event ProposalQueued(uint256 proposalId, uint256 eta);
    event ProposalExecuted(uint256 proposalId);

    function MIN_VOTING_PERIOD() external view returns (uint256);
    function MIN_VOTING_DELAY() external view returns (uint256);
    function MIN_PROPOSAL_THRESHOLD() external view returns (uint256);

    function comp() external view returns (address); // for testnet only
    function token() external view returns (address);
    function proposalEta(uint256) external view returns (uint256);
    function timelock() external view returns (address);
    function proposalCount() external view returns (uint256);
    function proposals(uint256 proposalId) external view returns (Proposal memory);
    function votingDelay() external view returns (uint256);
    function votingPeriod() external view returns (uint256);
    function state(uint256 proposalId) external view returns (ProposalState);
    function propose(
        address[] memory targets,
        uint256[] memory values,
        bytes[] memory calldatas,
        string memory description
    ) external returns (uint256 proposalId);
    function queue(uint256 proposalId) external;
    function execute(uint256 proposalId) external;
    function castVote(uint256 proposalId, uint8 support) external returns (uint256 balance);
    function proposalDetails(uint proposalId) external view returns (address[] memory targets, uint[] memory values, bytes[] memory calldatas, bytes32 descriptionHash);
    function proposalSnapshot(uint256 proposalId) external view returns (uint256);
    function quorum(uint256 timepoint) external view returns (uint256);
    function proposalVotes(uint256 proposalId) external view returns (uint256 againstVotes, uint256 forVotes, uint256 abstainVotes);
    function proposalDeadline(uint256 proposalId) external view returns (uint256);
    function castVoteWithReason(uint256 proposalId, uint8 support, string calldata reason) external returns (uint256);
}
